int timer = 0;
void dfs(int u, int parent, vector<vector<int>>& adj,
         vector<int>& disc, vector<int>& low, vector<pair<int,int>>& bridges) {
    disc[u] = low[u] = ++timer;
    for (int v : adj[u]) {
        if (v == parent) continue;              // skip the edge we came from
        if (disc[v] == 0) {                      // v unvisited: tree edge
            dfs(v, u, adj, disc, low, bridges);
            low[u] = min(low[u], low[v]);
            if (low[v] > disc[u]) bridges.push_back({u, v});   // bridge found
        } else {
            low[u] = min(low[u], disc[v]);       // back edge
        }
    }
}

