def find_bridges(n, adj):
    disc = [0] * n
    low = [0] * n
    bridges = []
    timer = [0]
    def dfs(u, parent):
        timer[0] += 1
        disc[u] = low[u] = timer[0]
        for v in adj[u]:
            if v == parent:
                continue                     # skip the edge we came from
            if disc[v] == 0:                  # tree edge
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v))    # bridge found
            else:
                low[u] = min(low[u], disc[v]) # back edge
    for i in range(n):
        if disc[i] == 0:
            dfs(i, -1)
    return bridges

