function findBridges(n, adj) {
  const disc = new Array(n).fill(0), low = new Array(n).fill(0), bridges = [];
  let timer = 0;
  const dfs = (u, parent) => {
    disc[u] = low[u] = ++timer;
    for (const v of adj[u]) {
      if (v === parent) continue;             // skip the edge we came from
      if (disc[v] === 0) {                     // tree edge
        dfs(v, u);
        low[u] = Math.min(low[u], low[v]);
        if (low[v] > disc[u]) bridges.push([u, v]);   // bridge found
      } else {
        low[u] = Math.min(low[u], disc[v]);    // back edge
      }
    }
  };
  for (let i = 0; i < n; i++) if (disc[i] === 0) dfs(i, -1);
  return bridges;
}
